function l(t){if(!t)return"—";const e=new Date(t);if(Number.isNaN(e.getTime()))return t;const n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}:${n(e.getSeconds())}`}const i={pending:{type:"info",label:"待登录"},online:{type:"success",label:"在线"},expired:{type:"danger",label:"凭证失效"},disabled:{type:"warning",label:"已停用"}},a={1:{type:"warning",label:"待支付"},3:{type:"primary",label:"制作中"},6:{type:"success",label:"已完成"},7:{type:"info",label:"已取消"}};function u(t){return a[t]||{type:"info",label:`状态${t}`}}function o(t){if(t==null||t<0)return"—";const e=Math.floor(t/60),n=Math.floor(t%60);return`${String(e).padStart(2,"0")}:${String(n).padStart(2,"0")}`}function f(t){return t==null?"—":t<60?`${t} 秒`:`${Math.floor(t/60)} 分 ${t%60} 秒`}export{a as O,i as S,o as a,f as b,l as f,u as o};
